interface User {
  id: string;
  orgId: string;
  org?: any;
}

interface Org {
  id: string;
  name: string;
}

async function loadUser(id: string): Promise<User> {
  const res = await fetch(`/api/users/${id}`);
  if (!res.ok) {
    throw new Error(`bad status ${res.status}`);
  }
  const user = await res.json() as User;

  const orgRes = await fetch(`/api/orgs/${user.orgId}`);
  if (!orgRes.ok) {
    throw new Error(`bad status ${orgRes.status}`);
  }
  const org = await orgRes.json() as Org;
  user.org = org;

  return user;
}

async function loadUsers(ids: string[]): Promise<User[]> {
  const results = await Promise.all(ids.map((id) => loadUser(id)));
  return results;
}

export { loadUser, loadUsers };
